package org.brightstats.model;
import java.util.*;
import com.google.gson.*;
import org.brightstats.model.TypedDiagram.*;
import org.brightstats.model.ElementType.Family;
import org.brightstats.stats.*;

/** Deterministic migration templates; subsequent edits retain persisted identities. */
public final class DiagramTemplates {
    private DiagramTemplates(){}
    private static Node root(JsonObject options){return new Node("root",ElementType.ROOT,"Model",0,0,options);}
    private static JsonObject column(String name){var properties=new JsonObject();properties.addProperty("column",name);return properties;}
    private static Link link(String id,ElementType type,String source,String target,JsonObject properties){return new Link(id,type,source,target,properties);}
    public static Document pls(List<String> names,List<PlsSem.Block> blocks,List<PlsSem.Edge> edges){List<Node> nodes=new ArrayList<>();nodes.add(root(new JsonObject()));List<Link> links=new ArrayList<>();Set<Integer> observed=new HashSet<>();var gson=new Gson();for(int i=0;i<blocks.size();i++){var block=blocks.get(i);JsonObject properties=new JsonObject();properties.addProperty("mode",block.mode().name());properties.addProperty("measurementType",block.measurementType().name());if(block.initialWeights()!=null)properties.add("initialWeights",gson.toJsonTree(block.initialWeights()));nodes.add(new Node("c"+i,ElementType.LATENT_VARIABLE,block.name(),320+350*(i%3),150+300*(i/3),properties));int position=0;for(int index:block.columns()){if(index<0||index>=names.size())throw new IllegalArgumentException("PLS template indicator lies outside the dataset.");if(observed.add(index))nodes.add(new Node("v"+index,ElementType.STANDARD_MANIFEST_VARIABLE,names.get(index),90+350*(i%3),80+300*(i/3)+70*position,column(names.get(index))));links.add(link("measurement_"+i+"_"+position,ElementType.CONNECTION_BETWEEN_LV_AND_MV,"c"+i,"v"+index,new JsonObject()));position++;}}for(int i=0;i<edges.size();i++){var edge=edges.get(i);links.add(link("path"+i,ElementType.CONNECTION_BETWEEN_LV_AND_LV,"c"+edge.source(),"c"+edge.target(),new JsonObject()));}return DiagramLayouts.arrange(new Document(1,Family.PLS,"root",nodes,links,List.of()));}
    public static Document gsca(Gsca.Model model){List<Node> nodes=new ArrayList<>();nodes.add(root(new JsonObject()));List<Link> links=new ArrayList<>();boolean[][] weights=model.weights(),loadings=model.loadings(),paths=model.paths();double[][] initial=model.initialWeights();for(int j=0;j<model.components().size();j++){JsonObject properties=new JsonObject();boolean reflective=false;for(int i=0;i<model.indicators().size();i++)reflective|=loadings[i][j];properties.addProperty("measurementType",reflective?"REFLECTIVE":"FORMATIVE");nodes.add(new Node("g"+j,ElementType.GSCA_LATENT_VARIABLE,model.components().get(j),400,120+200*j,properties));}for(int i=0;i<model.indicators().size();i++){nodes.add(new Node("v"+i,ElementType.GSCA_STANDARD_MANIFEST_VARIABLE,model.indicators().get(i),100,80+70*i,column(model.indicators().get(i))));for(int j=0;j<model.components().size();j++)if(weights[i][j]||loadings[i][j]){JsonObject properties=new JsonObject();properties.addProperty("weight",weights[i][j]);properties.addProperty("loading",loadings[i][j]);properties.addProperty("initialWeight",initial[i][j]);links.add(link("measurement_"+i+"_"+j,ElementType.GSCA_CONNECTION_BETWEEN_LV_AND_MV,"g"+j,"v"+i,properties));}}for(int i=0;i<paths.length;i++)for(int j=0;j<paths.length;j++)if(paths[i][j])links.add(link("path_"+i+"_"+j,ElementType.GSCA_CONNECTION_BETWEEN_LV_AND_LV,"g"+i,"g"+j,new JsonObject()));return DiagramLayouts.arrange(new Document(1,Family.GSCA,"root",nodes,links,List.of()));}
    public static Document regression(List<String> names,int response,int[] predictors,boolean intercept){List<Node> nodes=new ArrayList<>();nodes.add(root(new JsonObject()));nodes.add(new Node("outcome",ElementType.REGRESSION_DEPENDENT_VARIABLE,names.get(response),550,200,column(names.get(response))));List<Link> links=new ArrayList<>();for(int i=0;i<predictors.length;i++){nodes.add(new Node("predictor"+i,ElementType.REGRESSION_INDEPENDENT_VARIABLE,names.get(predictors[i]),150,100+100*i,column(names.get(predictors[i]))));links.add(link("path"+i,ElementType.CONNECTION_BETWEEN_DEPENDENT_AND_INDEPENDENT_VARIABLE,"predictor"+i,"outcome",new JsonObject()));}if(intercept){nodes.add(new Node("intercept",ElementType.REGRESSION_INTERCEPT,"Intercept",350,60,new JsonObject()));links.add(link("intercept_path",ElementType.CONNECTION_BETWEEN_DEPENDENT_AND_INTERCEPT,"intercept","outcome",new JsonObject()));}return DiagramLayouts.arrange(new Document(1,Family.REGRESSION,"root",nodes,links,List.of()));}
    public static Document process(List<String> names,PathProcess.Model model){Set<Integer> used=new TreeSet<>();used.add(model.source());used.add(model.target());for(var path:model.paths()){used.add(path.source());used.add(path.target());for(int moderator:path.moderators())used.add(moderator);}for(int control:model.controls())used.add(control);Set<Integer> controls=new HashSet<>();for(int control:model.controls())controls.add(control);JsonObject properties=new JsonObject();properties.addProperty("focalSource","p"+model.source());properties.addProperty("focalTarget","p"+model.target());List<Node> nodes=new ArrayList<>();nodes.add(root(properties));int position=0;for(int index:used){JsonObject binding=new JsonObject();JsonArray columns=new JsonArray();columns.add(names.get(index));binding.add("columns",columns);binding.addProperty("aggregation","MEAN");nodes.add(new Node("p"+index,controls.contains(index)?ElementType.PROCESS_MODEL_CONTROL_VARIABLE:ElementType.PROCESS_MODEL_LATENT_VARIABLE,names.get(index),180+300*(position%3),140+180*(position/3),binding));position++;}List<Link> links=new ArrayList<>();for(int i=0;i<model.paths().size();i++){var path=model.paths().get(i);String edge="path"+i;links.add(link(edge,controls.contains(path.source())||controls.contains(path.target())?ElementType.CONNECTION_BETWEEN_PROCESS_LV_AND_PROCESS_CV:ElementType.CONNECTION_BETWEEN_PROCESS_LV_AND_PROCESS_LV,"p"+path.source(),"p"+path.target(),new JsonObject()));for(int j=0;j<path.moderators().length;j++){String anchor="anchor_"+i+"_"+j;JsonObject binding=new JsonObject();binding.addProperty("edge",edge);nodes.add(new Node(anchor,ElementType.DONGLE,"",0,0,binding));String modifier="moderator_"+i+"_"+j;links.add(link(modifier,ElementType.CONNECTION_FOR_PROCESS_MODERATION,"p"+path.moderators()[j],anchor,new JsonObject()));edge=modifier;}}return DiagramLayouts.arrange(new Document(1,Family.PROCESS,"root",nodes,links,List.of()));}
    public static Document sem(SemModel.Model model,boolean meanStructure){int size=model.variables().size();Set<Integer> observed=new HashSet<>();for(int index:model.observed())observed.add(index);Map<String,SemModel.Parameter> parameters=new HashMap<>();for(var parameter:model.parameters())for(var location:parameter.locations()){int row=location.kind()==SemModel.Kind.COVARIANCE?Math.min(location.row(),location.column()):location.row(),col=location.kind()==SemModel.Kind.COVARIANCE?Math.max(location.row(),location.column()):location.column();parameters.put(location.kind()+":"+row+":"+col,parameter);}JsonObject options=new JsonObject();options.addProperty("meanStructure",meanStructure);List<Node> nodes=new ArrayList<>();nodes.add(root(options));List<Link> links=new ArrayList<>();double[][] a=model.directed(),s=model.covariance();double[] means=model.intercepts();for(int i=0;i<size;i++){boolean manifest=observed.contains(i);String name=model.variables().get(i);JsonObject properties=manifest?column(name):new JsonObject();if(!manifest)properties.addProperty("autoMarker",false);if(meanStructure)properties.add("mean",parameter(parameters.get(SemModel.Kind.INTERCEPT+":"+i+":0"),means[i]));String label=!manifest&&name.startsWith("Factor: ")?name.substring(8):name;nodes.add(new Node("ram"+i,manifest?ElementType.CBSEM_STANDARD_MANIFEST_VARIABLE:ElementType.CBSEM_LATENT_VARIABLE,label,manifest?650:300,100+100*i,properties));JsonObject variance=new JsonObject();variance.add("variance",parameter(parameters.get(SemModel.Kind.COVARIANCE+":"+i+":"+i),s[i][i]));nodes.add(new Node("error"+i,ElementType.CBSEM_ERROR_TERM,"e"+(i+1),manifest?850:100,100+100*i,variance));links.add(link("error_binding"+i,manifest?ElementType.CBSEM_CONNECTION_BETWEEN_MV_AND_ERROR_TERM:ElementType.CBSEM_CONNECTION_BETWEEN_LV_AND_ERROR_TERM,"error"+i,"ram"+i,new JsonObject()));}
        for(int target=0;target<size;target++)for(int source=0;source<size;source++){var parameter=parameters.get(SemModel.Kind.DIRECTED+":"+target+":"+source);if(a[target][source]!=0||parameter!=null){ElementType type=observed.contains(source)&&observed.contains(target)?ElementType.CBSEM_CONNECTION_BETWEEN_MV_AND_MV:!observed.contains(source)&&!observed.contains(target)?ElementType.CBSEM_CONNECTION_BETWEEN_LV_AND_LV:ElementType.CBSEM_CONNECTION_BETWEEN_LV_AND_MV;links.add(link("path_"+source+"_"+target,type,"ram"+source,"ram"+target,parameter(parameter,a[target][source])));}}for(int i=0;i<size;i++)for(int j=i+1;j<size;j++){var parameter=parameters.get(SemModel.Kind.COVARIANCE+":"+i+":"+j);if(s[i][j]!=0||parameter!=null)links.add(link("covariance_"+i+"_"+j,ElementType.CBSEM_CORRELATION_CONNECTION_BETWEEN_ERROR_TERM_AND_ERROR_TERM,"error"+i,"error"+j,parameter(parameter,s[i][j])));}return DiagramLayouts.arrange(new Document(1,Family.CBSEM,"root",nodes,links,List.of()));}
    private static JsonObject parameter(SemModel.Parameter parameter,double fixed){JsonObject value=new JsonObject();value.addProperty("free",parameter!=null);value.addProperty("value",parameter==null?fixed:parameter.start());if(parameter!=null){value.addProperty("equality",parameter.name());value.addProperty("scale",parameter.scale());if(parameter.lower()!=null)value.addProperty("lower",parameter.lower());else value.add("lower",JsonNull.INSTANCE);if(parameter.upper()!=null)value.addProperty("upper",parameter.upper());else value.add("upper",JsonNull.INSTANCE);}return value;}
}
